let md = key.map(pmid => {
  const a = byId[pmid];
  if(!a) return `## ${pmid} (missing)`;
  const doi = a.identifiers.doi ? `DOI: ${a.identifiers.doi}` : "";
  return `## ${pmid} | ${a.publication_date.year} | ${a.journal.title}\n**${a.title}**\n${doi}\n\n${(a.abstract||"(no abstract)").replace(/\s+/g," ")}`;
}).join("\n\n---\n\n");
